from pathlib import Path
from datetime import datetime, timezone
import json, hashlib, re
from html.parser import HTMLParser

S = Path(__file__).resolve().parent
AT = datetime.now(timezone.utc).isoformat()
sha = lambda p: hashlib.sha256(p.read_bytes()).hexdigest()
def write(name, obj):
    p = S / name; assert not p.exists(); p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(obj, indent=2, ensure_ascii=False) + '\n')
def cap(name):
    p = S / 'captures' / name
    receipt = p.with_name(p.stem + '.receipt.json')
    return dict(path='captures/' + name, sha256=sha(p), receipt=json.loads(receipt.read_text()) if receipt.exists() else None)

