    dict(candidate='FOODON:03315306', label='protein hydrolyzates', scope='SIREN flavoring/spice/herb text is rdfs:comment. Separate actual OWL subclass restriction is member_of some FOODON:03400181 food additive (us cfr).', conclusion='Initial guarded candidate is unselected after NEW01. It is insufficient to say no flavoring role is imported: actual food-additive membership scope also needs support absent from these unqualified observations.', missing_fact='Evidence that this source material falls within the asserted food-additive membership scope, or authoritative ontology clarification removing/broadening the restriction.', sources=['foodon15306.json', 'foodon15306-parents.json', 'foodon15306-memberof.json', 'foodon15306-graph.json', 'foodon-official-owl.json']),
