# The raw official OWL is immutable; this extraction is a readable exact substring locator, not replacement evidence.
owl = (S / 'captures/foodon-official-owl.json').read_text()
classes = {}
for ident in ['FOODON_03315306', 'FOODON_00001872', 'FOODON_03400181', 'FOODON_03460227']:
    pattern = r'<owl:Class rdf:about="http://purl.obolibrary.org/obo/' + ident + r'">.*?</owl:Class>'
    hit = re.search(pattern, owl, re.S); assert hit
    classes[ident] = dict(exact_text=hit.group(0), character_offset_start=hit.start(), character_offset_end=hit.end())
write('read/foodon-exact-class-locators.json', dict(full_source=cap('foodon-official-owl.json'), classes=classes))
receipts = [json.loads(p.read_text()) for p in sorted((S / 'captures').glob('*.receipt.json'))]
write('all-capture-index.json', dict(at=AT, assessor='/root/buffer_hepes', captures=receipts, rule='Each actual retrieval time remains as recorded. The Thermo PDF is exact reused bytes with the earlier retriever/time; current applicability assessment is distinct. File suffix .json can contain raw HTML/XML; content_type and actual bytes govern.'))
print(json.dumps(dict(alternatives=len(matrix), captures=len(receipts))))
